-- GalleryGo 2.0 SQLite schema baseline; runtime migrations must version/checksum this schema.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','user')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_hash TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS permission_groups(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_groups(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES permission_groups(id) ON DELETE CASCADE, PRIMARY KEY(user_id,group_id));
CREATE TABLE IF NOT EXISTS libraries(id TEXT PRIMARY KEY, name TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE RESTRICT, name TEXT NOT NULL, root_path TEXT NOT NULL UNIQUE, mapping_json TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'unknown' CHECK(state IN ('unknown','healthy','unavailable','error')), last_healthy_at INTEGER, scan_generation INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY, source_name TEXT NOT NULL, display_name TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS albums(id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id), source_id TEXT REFERENCES sources(id), person_id TEXT REFERENCES people(id), source_name TEXT NOT NULL, display_name TEXT, relative_path TEXT, cover_media_id TEXT, quarantined_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_albums_library ON albums(library_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_album_source_path ON albums(source_id,relative_path) WHERE source_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS album_access(album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES permission_groups(id) ON DELETE RESTRICT, PRIMARY KEY(album_id,group_id));
CREATE TABLE IF NOT EXISTS library_access(library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES permission_groups(id) ON DELETE RESTRICT, PRIMARY KEY(library_id,group_id));
CREATE TABLE IF NOT EXISTS source_entries(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), relative_path TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), mtime_ns INTEGER NOT NULL, quick_fingerprint TEXT, sha256 TEXT, seen_generation INTEGER NOT NULL DEFAULT 0, availability TEXT NOT NULL DEFAULT 'present' CHECK(availability IN('present','unavailable','quarantined')), updated_at INTEGER NOT NULL, UNIQUE(source_id,relative_path));
CREATE INDEX IF NOT EXISTS idx_entry_source_generation ON source_entries(source_id,seen_generation);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY, album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE RESTRICT, source_entry_id TEXT REFERENCES source_entries(id), kind TEXT NOT NULL CHECK(kind IN('image','video')), file_name TEXT NOT NULL, capture_at INTEGER, width INTEGER, height INTEGER, duration_ms INTEGER, orientation INTEGER, mime TEXT, current_revision_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_media_album ON media(album_id,id);
CREATE TABLE IF NOT EXISTS media_revisions(id TEXT PRIMARY KEY, media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE, source_sha256 TEXT NOT NULL, source_size INTEGER NOT NULL, source_mtime_ns INTEGER NOT NULL, version INTEGER NOT NULL, created_at INTEGER NOT NULL, UNIQUE(media_id,version));
CREATE TABLE IF NOT EXISTS media_variants(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES media_revisions(id) ON DELETE CASCADE, preset_key TEXT NOT NULL, preset_version INTEGER NOT NULL, storage_path TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), sha256 TEXT NOT NULL, width INTEGER, height INTEGER, duration_ms INTEGER, status TEXT NOT NULL CHECK(status IN('ready','failed','retired')), created_at INTEGER NOT NULL, UNIQUE(revision_id,preset_key,preset_version));
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS album_tags(album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(album_id,tag_id));
CREATE TABLE IF NOT EXISTS favorite_collections(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, parent_id TEXT REFERENCES favorite_collections(id), name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_collection_user_parent_name ON favorite_collections(user_id,COALESCE(parent_id,''),name);
CREATE TABLE IF NOT EXISTS favorites(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE CASCADE, collection_id TEXT REFERENCES favorite_collections(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,album_id));
CREATE TABLE IF NOT EXISTS ratings(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE CASCADE, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), updated_at INTEGER NOT NULL, PRIMARY KEY(user_id,album_id));
CREATE TABLE IF NOT EXISTS playlists(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS playlist_items(playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE, position INTEGER NOT NULL, PRIMARY KEY(playlist_id,media_id), UNIQUE(playlist_id,position));
CREATE TABLE IF NOT EXISTS playback_progress(user_id TEXT NOT NULL REFERENCES users(id), playlist_id TEXT NOT NULL REFERENCES playlists(id), media_id TEXT REFERENCES media(id), offset_ms INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, PRIMARY KEY(user_id,playlist_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, resource_key TEXT, dedupe_key TEXT UNIQUE, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('queued','running','succeeded','failed','cancelled','dead')), priority INTEGER NOT NULL DEFAULT 0, cancel_requested INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, lease_expires_at INTEGER, heartbeat_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, next_run_at INTEGER NOT NULL, total INTEGER NOT NULL DEFAULT 0, done INTEGER NOT NULL DEFAULT 0, succeeded INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_jobs_claim ON jobs(status,next_run_at,priority,created_at);
CREATE TABLE IF NOT EXISTS job_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, attempt INTEGER NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER, status TEXT NOT NULL, error_code TEXT, message TEXT, UNIQUE(job_id,attempt));
CREATE TABLE IF NOT EXISTS change_log(seq INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, resource_id TEXT NOT NULL, operation TEXT NOT NULL, version INTEGER NOT NULL, payload_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_events(id TEXT PRIMARY KEY, change_seq INTEGER NOT NULL REFERENCES change_log(seq), published_at INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sync_operations(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), result_json TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, actor_user_id TEXT, event_type TEXT NOT NULL, resource_type TEXT, resource_id TEXT, detail_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS album_search USING fts5(album_id UNINDEXED,title,person,tags,filename,tokenize='trigram');
-- NOTE: album_search authorization must always JOIN albums/library_access/album_access in query.
-- NOTE: media.current_revision_id and albums.cover_media_id are app-managed relationships;
--       migration implementation must add validation on assignment and repair checks.
